"""This file contains the Sim Dialogs Gantry Page Object class for the SIM GANTRY pane
in the Sim Dialogs XVI test tool"""

import logging
from . import SimDialogs
from .. interactions import SimDialogGantryFuncs
from typing import Dict
from typing import Optional as opt


logger = logging.getLogger(__name__)

class SimDialogsGantry(SimDialogs):
    '''Page Object class for the SIM GANTRY pane'''

    def __init__(self, host_address: str ="192.168.30.4") -> None:
        super().__init__(host_address)

    def toggle_sim_gantry_node_online_checkbox(self, enable_checkbox: bool=True) -> None:
        '''
        Toggles the Node Online checkbox in the Sim Gantry Pane to either checked
        or unchecked

        Args:
            enable_checkbox (bool): True to check checkbox, False to uncheck
        '''
        if enable_checkbox:
            SimDialogGantryFuncs.check_sim_gantry_node_online_checkbox()
        else:
            SimDialogGantryFuncs.uncheck_sim_gantry_node_online_checkbox()

    def select_sim_gantry_asu_button(self) -> None:
        '''Clicks the ASU button on the Sim Gantry Pane'''
        SimDialogGantryFuncs.click_sim_gantry_asu_button()

    def read_sim_gantry_field_values(self, field_to_read: str) -> opt[str]:
        '''
        Gets the specified Sim Gantry field value and returns it if found.

        Args:
            field_to_read (str): Name of Sim gantry field to read value from.
                                 Can be one of the following:
                                 "Target", "Current" or "Speed"
        Returns:
            str or None: Sim Gantry field value or None if not found
        '''
        if field_to_read.casefold() == "Target".casefold():
            return SimDialogGantryFuncs.get_sim_gantry_target_textfield()
        elif field_to_read.casefold() == "Current".casefold():
            return SimDialogGantryFuncs.get_sim_gantry_current_textfield()
        elif field_to_read.casefold() == "Speed".casefold():
            return SimDialogGantryFuncs.get_sim_gantry_current_textfield()
        else:
            logger.info(f"Invalid Sim Gantry field: {field_to_read}, unable to read")
            return None

    def set_sim_gantry_field_values(self, setting_type_value_pairs: Dict[str, str]) -> None:
        '''
        Modifies one or more Sim Gantry fields as specified in the dictionary arg of field
        type key: set value pairs

        Args:
            setting_type_value_pairs (dict of str: str): Dictionary of field type name
            to set string as the key, and string value to set as the value.

            Setting type field Keys can be one of the following strings:
            "Target", "Current", "Speed" or "Fault"

            Value can be a numeric value as a string
        '''
        for key, value in setting_type_value_pairs.items():
            if key.casefold() == "Target".casefold():
                SimDialogGantryFuncs.edit_sim_gantry_target_textfield(value)
            elif key.casefold() == "Current".casefold():
                SimDialogGantryFuncs.edit_sim_gantry_current_textfield(value)
            elif key.casefold() == "Speed".casefold():
                SimDialogGantryFuncs.edit_sim_gantry_speed_textfield(value)
            elif key.casefold() == "Fault".casefold():
                SimDialogGantryFuncs.edit_sim_gantry_fault_textfield(value)
            else:
                logger.info(f"Invalid Sim Gantry field type: {key}, unable to set")

    def toggle_sim_gantry_target_auto_checkbox(self, enable_checkbox: bool=True) -> None:
        '''
        Toggles the Target Auto checkbox in the Sim Gantry Pane to either checked
        or unchecked

        Args:
            enable_checkbox (bool): True to check checkbox, False to uncheck
        '''
        if enable_checkbox:
            SimDialogGantryFuncs.check_sim_gantry_target_auto_checkbox()
        else:
            SimDialogGantryFuncs.uncheck_sim_gantry_target_auto_checkbox()

    def toggle_sim_gantry_current_auto_checkbox(self, enable_checkbox: bool=True) -> None:
        '''
        Toggles the Current Auto checkbox in the Sim Gantry Pane to either checked
        or unchecked

        Args:
            enable_checkbox (bool): True to check checkbox, False to uncheck
        '''
        if enable_checkbox:
            SimDialogGantryFuncs.check_sim_gantry_current_auto_checkbox()
        else:
            SimDialogGantryFuncs.uncheck_sim_gantry_current_auto_checkbox()

    def toggle_sim_gantry_speed_auto_checkbox(self, enable_checkbox: bool=True) -> None:
        '''
        Toggles the Speed Auto checkbox in the Sim Gantry Pane to either checked
        or unchecked

        Args:
            enable_checkbox (bool): True to check checkbox, False to uncheck
        '''
        if enable_checkbox:
            SimDialogGantryFuncs.check_sim_gantry_speed_auto_checkbox()
        else:
            SimDialogGantryFuncs.uncheck_sim_gantry_speed_auto_checkbox()

    def toggle_sim_gantry_fault_checkbox(self, enable_checkbox: bool=True) -> None:
        '''
        Toggles the fault checkbox in the Sim Gantry Pane to either checked
        or unchecked

        Args:
            enable_checkbox (bool): True to check checkbox, False to uncheck
        '''
        if enable_checkbox:
            SimDialogGantryFuncs.check_sim_gantry_fault_checkbox()
        else:
            SimDialogGantryFuncs.uncheck_sim_gantry_fault_checkbox()